  const ht = (key) => HOME_T[key]?.[hlc] ?? HOME_T[key]?.en ?? HOME_T[key]?.ko ?? "";

  // ✅ V148: 기존 가입자 마이그레이션 체크 (dataOwnershipAgreed 없으면 팝업)
  useEffect(()=>{
    if(!user) return;
    getDoc(doc(db, "users", user.uid)).then(d => {
      if(d.exists() && d.data().dataOwnershipAgreed === undefined) {
        setShowMigration(true);
      }
    }).catch(()=>{});
  },[user]);

  // ✅ V349: SW 캐시 버스팅 + 캐시 버스팅 팝업
  useEffect(()=>{
    const APP_VERSION = "363";
    const VER_KEY = "hc_app_ver";
    const stored = localStorage.getItem(VER_KEY);
    if (stored && stored !== APP_VERSION) {
      // 버전이 다르면 팝업 표시
      setShowCacheBust(true);
    }
    localStorage.setItem(VER_KEY, APP_VERSION);

    // SW 등록 + 버전 전달 + SW_UPDATED 수신 시 자동 새로고침
    if ("serviceWorker" in navigator) {
      // SW_UPDATED 메시지 수신 → 자동 새로고침
      navigator.serviceWorker.addEventListener("message", (e) => {
        if (e.data?.type === "SW_UPDATED") {
          window.location.reload(true);
        }
      });

      navigator.serviceWorker.register("/sw.js").then(reg => {
        const sw = reg.active || reg.installing || reg.waiting;
        if (sw) sw.postMessage({ type: "SET_VERSION", version: APP_VERSION });
        navigator.serviceWorker.ready.then(r => {
          r.active?.postMessage({ type: "SET_VERSION", version: APP_VERSION });
        });

        // SW 없는 첫 방문 기기 — 컨트롤러 없으면 즉시 새로고침
        if (!navigator.serviceWorker.controller) {
          navigator.serviceWorker.ready.then(() => {
            if (navigator.serviceWorker.controller) {
              window.location.reload(true);
            }
          });
        }
      }).catch(()=>{});
    }
  }, []);

  // ✅ V336: beforeinstallprompt 이벤트 캐치 (Android Chrome PWA 설치용)
  useEffect(()=>{
    const handler = (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener("beforeinstallprompt", handler);
    return () => window.removeEventListener("beforeinstallprompt", handler);
  }, []);

  // ✅ V148: 로그인 후 role 로드
  useEffect(()=>{
    if(!user) return;
    getDoc(doc(db, "users", user.uid)).then(d => {
      if(d.exists()) {
        setUserRole(d.data().role || "learner");
        // ✅ V340: 중급 자기선언 상태 복원
        if(d.data().midLevel === true) setMidLevel(true);
      }
    }).catch(()=>setUserRole("learner"));
  },[user]);

  // ✅ V148: URL ?join= 파라미터 감지
  useEffect(()=>{
    const params = new URLSearchParams(window.location.search);
    const code = params.get("join");
    if(code) setJoinCode(code.toUpperCase());
  },[]);

  // ✅ V143: 로그인 후 방문 횟수 확인 (최대 3회)
  useEffect(()=>{
    if(!user) return;
    const key = `hc_promo_${user.uid}`;
    const count = parseInt(localStorage.getItem(key)||"0");
    if(count < 3){ setShowPromo(true); localStorage.setItem(key, String(count+1)); }
  },[user]);

  // ✅ V333: 로그인 후 이어서 학습 팝업 — 저장된 step이 있으면 팝업 표시
  useEffect(()=>{
    if(!user) return;
    try {
      const saved = localStorage.getItem(`hc_step_${user.uid}`);
      const skipSteps = ["lang","curriculum","plan","learn","pronContents",""];
      if(saved && !skipSteps.includes(saved)){
        setResumeStep(saved);
        setShowResumePopup(true);
      }
    } catch(e) {}
  },[user]);
  const {speaking, ttsHint, unlock, speak} = useTTS();

  useEffect(()=>{
    const unsub = onAuthStateChanged(auth, u => setUser(u||null));
    return ()=>unsub();
  },[]);

  async function handleLogout() {
    await signOut(auth);
    setLevel(null); setTab("speak"); setShowTopikChoice(false); setBegReady(false); setShowTopik2Choice(false); setShowCurricPreview(true); setBrowseMode(false);
  }

  if (user===undefined) return (
    <div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",background:C.bg}}>
      <div style={{fontSize:40}}>🇰🇷</div>
    </div>
  );

  // ✅ V275: 온보딩 — 로그인 전, 최초 1회
  // ✅ V336: PWA 설치 유도 팝업
